#define BATCH_PRUNING_NO_MAIN
#include "batch_pruning.cpp"
#undef BATCH_PRUNING_NO_MAIN

struct Xbox{std::vector<int>ids;std::vector<uint8_t>mn,mx;};
struct XCfg{std::string data="../dataset/sift",assign="../populated_index/PriorMax_SIFT1M_C100_clusterid.tsv",out="box_batch_results.csv";int base=100000,nq=50,k=100;std::vector<int>probes{8,16,32,64,100},blocks{4,8,16,32,64,128};};
static XCfg xparse(int ac,char**av){XCfg c;for(int i=1;i<ac;++i){std::string a=av[i];auto v=[&](){if(++i==ac)throw std::runtime_error("missing value");return std::string(av[i]);};if(a=="--dataset")c.data=v();else if(a=="--assignments")c.assign=v();else if(a=="--output")c.out=v();else if(a=="--base")c.base=std::stoi(v());else if(a=="--queries")c.nq=std::stoi(v());else if(a=="--k")c.k=std::stoi(v());else if(a=="--nprobes")c.probes=bints(v());else if(a=="--block-sizes")c.blocks=bints(v());else throw std::runtime_error("unknown option "+a);}return c;}
static std::vector<Xbox>boxes(const BTree&t,const SQ4&sq){std::vector<Xbox>out;for(const BNode&n:t.nodes)if(n.leaf()){Xbox b;b.mn.assign(sq.d,15);b.mx.assign(sq.d,0);for(int p=n.begin;p<n.end;++p){int id=t.ids[p];b.ids.push_back(id);for(int j=0;j<sq.d;++j){uint8_t c=sq.code[(size_t)id*sq.d+j];b.mn[j]=std::min(b.mn[j],c);b.mx[j]=std::max(b.mx[j],c);}}out.push_back(std::move(b));}return out;}
static float box_lb(const float*q,const Xbox&b,const SQ4&sq){float s=0;for(int j=0;j<sq.d;++j){float lo=sq.lo[j]+(b.mn[j]-0.5f)*sq.step[j],hi=sq.lo[j]+(b.mx[j]+0.5f)*sq.step[j];lo=std::nextafter(lo,-std::numeric_limits<float>::infinity());hi=std::nextafter(hi,std::numeric_limits<float>::infinity());float z=0;if(q[j]<lo)z=lo-q[j];else if(q[j]>hi)z=q[j]-hi;s+=z*z;}return std::sqrt(s);}
int main(int ac,char**av)try{XCfg cfg=xparse(ac,av);Matrix xb=fvecs(cfg.data+"/sift_base.fvecs",cfg.base),xq=fvecs(cfg.data+"/sift_query.fvecs",cfg.nq);auto ls=prefix_lists(cfg.assign,xb.rows());auto cs=centers(xb,ls);SQ4 sq(xb);struct Q{std::vector<int>clusters;float tau;uint64_t vis=0,fexact=0;};std::vector<std::vector<Q>>qs(cfg.probes.size(),std::vector<Q>(xq.rows()));for(size_t pi=0;pi<cfg.probes.size();++pi)for(size_t qi=0;qi<xq.rows();++qi){int np=cfg.probes[pi];Q&q=qs[pi][qi];std::vector<int>pr(100);std::iota(pr.begin(),pr.end(),0);std::partial_sort(pr.begin(),pr.begin()+np,pr.end(),[&](int a,int b){float x=l2(xq[qi],cs[a].data(),xb.d),y=l2(xq[qi],cs[b].data(),xb.d);return x<y||(x==y&&a<b);});q.clusters.assign(pr.begin(),pr.begin()+np);std::priority_queue<std::pair<float,int>>top;for(int c:q.clusters)for(int id:ls[c]){float d=l2(xq[qi],xb[id],xb.d);++q.vis;if((int)top.size()<cfg.k)top.push({d,id});else if(d<top.top().first){top.pop();top.push({d,id});}}q.tau=std::sqrt(top.top().first);for(int c:q.clusters)for(int id:ls[c])q.fexact+=sq.lb(xq[qi],id)<=q.tau;}
std::ofstream out(cfg.out);out<<"base,k,nprobe,block_size,avg_boxes,avg_box_size,prune_ratio,avg_opened,avg_exact,summary_bytes,flat_bytes,box_bytes,vo_reduction\n";std::cout<<"nprobe block prune reduction\n";for(int block:cfg.blocks){std::cerr<<"Building similarity boxes, max block="<<block<<"...\n";BatchForest forest(xb,sq,ls,block);std::vector<std::vector<Xbox>>bx(100);for(int c=0;c<100;++c)bx[c]=boxes(forest.trees[c],sq);for(size_t pi=0;pi<cfg.probes.size();++pi){uint64_t vis=0,fexact=0,nb=0,pruned=0,opened=0,exact=0;double summaries=0;for(size_t qi=0;qi<xq.rows();++qi){const Q&q=qs[pi][qi];vis+=q.vis;fexact+=q.fexact;for(int c:q.clusters)for(const Xbox&b:bx[c]){++nb;summaries+=40+sq.d;if(box_lb(xq[qi],b,sq)>q.tau)pruned+=b.ids.size();else{opened+=b.ids.size();for(int id:b.ids)if(sq.lb(xq[qi],id)<=q.tau)++exact;}}}double nq=xq.rows(),flat=vis*72.0/nq+fexact*512.0/nq,bytes=summaries/nq+opened*72.0/nq+exact*512.0/nq;out<<xb.rows()<<','<<cfg.k<<','<<cfg.probes[pi]<<','<<block<<','<<nb/nq<<','<<vis/(double)nb<<','<<pruned/(double)vis<<','<<opened/nq<<','<<exact/nq<<','<<summaries/nq<<','<<flat<<','<<bytes<<','<<1-bytes/flat<<'\n';std::cout<<std::setw(6)<<cfg.probes[pi]<<' '<<std::setw(5)<<block<<' '<<std::fixed<<std::setprecision(4)<<pruned/(double)vis<<' '<<1-bytes/flat<<'\n';}}
std::cerr<<"Wrote "<<cfg.out<<"\n";return 0;}catch(const std::exception&e){std::cerr<<"error: "<<e.what()<<'\n';return 1;}
